export const outlineVariants = Object.freeze({
    thin: Object.freeze({ attrs: Object.freeze({ strokeWidth: 1 }) }),
    regular: Object.freeze({ attrs: Object.freeze({ strokeWidth: 1.5 }) }),
    bold: Object.freeze({ attrs: Object.freeze({ strokeWidth: 2 }) }),
});
export const outlineWithSolidVariants = Object.freeze({
    ...outlineVariants,
    solid: Object.freeze({ attrs: Object.freeze({ fill: 'currentColor', stroke: 'none' }) }),
});
